HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K                                            # noqa: E402
K.console_encoding()

# ⚠️ 运行产物根**读配置**，不再硬编码 `_archive/lit-runs`（2026-10-10 迁移）。
#    `_cfg()` 尚未定义时不能求值，故这里是函数而非模块常量。
_RUNS_OVERRIDE = None          # 仅 --selftest 用


def runs_root():
    if _RUNS_OVERRIDE:
        return _RUNS_OVERRIDE
    return K.lit_runs_dir(_cfg())


def daily_root():
    return os.path.join(runs_root(), "daily")


def picks_root():
    return os.path.join(runs_root(), "picks")


# 渲染顺序与 ID 取值**共用同一个函数**，否则摘要里的编号与 --pick 会错位
SORT_KEY = lambda p: (-float(p.get("relevance") or 0.0), p.get("title") or "")   # noqa: E731


# ---------------------------------------------------------------- 候选装载

def _cfg():
    try:
        return K.load_lit_config()
    except Exception:                                          # noqa: BLE001
        return {}


def results_dir(cfg=None):
    """可点开的摘要落点（纯英文路径）。配置优先，缺省落在库内运行产物目录。"""
    cfg = cfg or _cfg()
    return ((cfg.get("automation") or {}).get("results_dir")
            or "")


def day_dirs(day=None):
    d = daily_root()
    if day:
        return [os.path.join(d, day)]
    if not os.path.isdir(d):
        return []
    ds = [x for x in sorted(os.listdir(d))
          if re.fullmatch(r"\d{4}-\d{2}-\d{2}", x)]
    return [os.path.join(d, x) for x in ds]


def load_day(day_dir):
    """读某天的候选：返回 (status, {slug: [papers]}, day, window)。"""
    status = {}
    sp = os.path.join(day_dir, "status.json")
    if os.path.exists(sp):
        try:
            with open(sp, encoding="utf-8") as f:
                status = json.load(f)
        except Exception:                                      # noqa: BLE001
            status = {}
    results = {}
    for p in sorted(glob.glob(os.path.join(day_dir, "cand_*.json"))):
        slug = os.path.basename(p)[len("cand_"):-len(".json")]
        try:
            with open(p, encoding="utf-8") as f:
                papers = json.load(f).get("papers") or []
        except Exception as e:                                 # noqa: BLE001
            print(f"[warn] 读 {p} 失败：{e}", file=sys.stderr)
            papers = []
        results[slug] = sorted(papers, key=SORT_KEY)
    window = (status.get("window") or "").strip()
    day = status.get("day") or os.path.basename(day_dir.rstrip("\\/"))
    return status, results, day, window


def all_slugs(status, results):
    """方向顺序：优先 status.json 里的顺序，其次字母序。"""
    order = [s for s in (status.get("directions") or [])]
    ordered = [d.get("slug") for d in order if isinstance(d, dict) and d.get("slug")]
    for s in sorted(results):
        if s not in ordered:
            ordered.append(s)
    return ordered


def label_of(status, slug):
    for d in (status.get("directions") or []):
        if isinstance(d, dict) and d.get("slug") == slug:
            return d.get("label") or slug
    return slug


# ---------------------------------------------------------------- 渲染

def fmt_paper(i, p):
    title = (p.get("title") or "").strip()
    journal = p.get("journal") or "?"
    date = (p.get("publication_date") or "")[:10]
    rel = p.get("relevance", 0)
    doi = p.get("doi") or ""
    oa = "OA" if p.get("is_oa") else "  "
    tier = p.get("journal_tier") or ""
    corr = p.get("corresponding_author") or ""
    line1 = (f"{i}. [{oa}] **{title}**\n"
             f"   - {journal} · {date} · 相关度 {rel}"
             + (f" · {tier}" if tier else "")
             + (f" · 通讯 {corr}" if corr else ""))
    line2 = f"   - DOI: https://doi.org/{doi}" if doi else "   - DOI: —"
    return line1 + "\n" + line2


def build_digest(day, status, results, window="", with_ids=False):
    """生成摘要 md。格式与既有 digest 保持一致，便于旧习惯与旧解析器继续工作。"""
    slugs = all_slugs(status, results)
    errs = {d.get("slug"): d.get("error")
            for d in (status.get("directions") or [])
            if isinstance(d, dict) and d.get("error")}
    total = sum(len(results.get(s) or []) for s in slugs)

    lines = [f"# lit-watch 每日发现 · {day}", ""]
    lines.append(f"\n**合计 {total} 篇候选**（{len(slugs)} 个方向）\n")
    cfg = _cfg()
    n_j = len(cfg.get("journals") or [])
    wl = (f"期刊白名单：Matsci KB `tools/lit_config.yaml`"
          + (f"（{n_j} 刊，分级 T0–T4）" if n_j else ""))
    lines.append(f"> 时间窗：{window or '见各方向'} ｜ {wl}\n")
    lines.append("> ⚠️ 仅为**候选**，未下载全文、未入库。审核后走 `/lit-watch` 阶段 B~D。"
                 "勾选命令：`python tools/lit_digest.py --pick \"battery#1,oer#2-5\"`\n")
    if errs:
        lines.append("> ❌ 本次有方向运行失败：" + "、".join(
            f"{k}（{str(v)[:60]}）" for k, v in errs.items()) + "\n")

    for slug in slugs:
        papers = results.get(slug) or []
        label = label_of(status, slug)
        if slug in errs and not papers:
            lines.append(f"\n## {label}（{slug}）\n\n- ❌ 本次运行失败：{str(errs[slug])[:200]}\n")
            continue
        lines.append(f"\n## {label}（{slug}）— {len(papers)} 篇\n")
        if not papers:
            lines.append("\n_本窗口无新文献（或均已在本地去重集内）_\n")
            continue
        for i, p in enumerate(papers, 1):
            block = fmt_paper(i, p)
            if with_ids:
                block = block.replace("   - DOI:", f"   - ID: {slug}#{i}\n   - DOI:", 1)
            lines.append(block + "\n")
    return "\n".join(lines)


def _write_text(path, text):
    """原子写文本（临时文件 + os.replace）。

    ⚠️ 为什么必须原子：`lit_daily` 会在每个方向后调本脚本渲染，而计划任务可能在
    渲染途中的任意时刻被外部终止（2026-10-09 的实际事故）。非原子写会留下**半截摘要**，
    而摘要正是给人看的唯一交付物。
    """
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    os.replace(tmp, path)


def render(day=None, window="", write_results=True, with_ids=False, quiet=False):
    """渲染指定日期（默认最近一天）的摘要；返回 (md, day, 落盘路径列表)。"""
    dirs = day_dirs(day)
    if not dirs:
        raise SystemExit(f"[!] 找不到任何每日运行目录（{daily_root()}/<日期>/）")
    day_dir = dirs[-1]
    status, results, day, win = load_day(day_dir)
    md = build_digest(day, status, results, window=window or win, with_ids=with_ids)

    written = []
    for p in (os.path.join(day_dir, "digest.md"),
              os.path.join(daily_root(), "latest-digest.md")):
        _write_text(p, md)
        written.append(p)
    if write_results:
        rd = results_dir()
        try:
            p = os.path.join(rd, f"lit-watch-daily-{day}.md")
            _write_text(p, md)
            written.append(p)
        except OSError as e:
            print(f"[warn] 结果目录不可写（{rd}）：{e}", file=sys.stderr)
    if not quiet:
        for p in written:
            print(f"摘要已写入: {p}")
    return md, day, written


# ---------------------------------------------------------------- 勾选

def iter_ids(spec, results):
    """把 'battery#1,oer#2-5,all' 展开成 [(slug, idx, paper)]。idx 从 1 起。"""
    picked = []
    specs = [s.strip() for s in (spec or "").split(",") if s.strip()]
    for s in specs:
        if s.lower() == "all":
            for slug in sorted(results):
                for i, p in enumerate(results[slug], 1):
                    picked.append((slug, i, p))
            continue
        m = re.fullmatch(r"([A-Za-z0-9._\-]+)#(\d+)(?:-(\d+))?", s)
        if not m:
            raise SystemExit(f"[!] 看不懂的选择项：{s}（应为 slug#n、slug#a-b 或 all）")
        slug, a = m.group(1), int(m.group(2))
        b = int(m.group(3)) if m.group(3) else a
        papers = results.get(slug)
        if papers is None:
            raise SystemExit(f"[!] 没有方向 {slug}；可用：{', '.join(sorted(results))}")
        for i in range(a, b + 1):
            if 1 <= i <= len(papers):
                picked.append((slug, i, papers[i - 1]))
            else:
                print(f"[warn] {slug}#{i} 超出范围（该方向 {len(papers)} 篇），跳过",
                      file=sys.stderr)
    return picked


def apply_filters(picked, min_rel=None, only_oa=False, limit=0):
    out = []
    for slug, i, p in picked:
        if min_rel is not None and float(p.get("relevance") or 0) < min_rel:
            continue
        if only_oa and not p.get("is_oa"):
            continue
        out.append((slug, i, p))
    if limit:
        out = out[:limit]
    return out


def write_picks(picked, day, out_path="", quiet=False):
    """写出 lit_fetch 可直接吃的候选 JSON（保留全部字段）。"""
    papers = []
    for slug, i, p in picked:
        q = dict(p)
        q["pick_id"] = f"{slug}#{i}"
        q["direction"] = q.get("direction") or slug
        papers.append(q)
    if not out_path:
        os.makedirs(picks_root(), exist_ok=True)
        # ⚠️ 文件名带**时分秒**：旧版是 `<日期>-picks.json`，同一天第二次勾选会
        #    静默覆盖第一次的选择（且没有任何提示）。lit_fetch 的结果文件早就是
        #    时间戳命名了，这里对齐。
        #    再加 `-2/-3…` 后缀兜底：同一秒内连做两次勾选（脚本化时很常见）
        #    仍然会撞名，撞名就等于覆盖 —— 那就不是"时间戳"能解决的问题了。
        stamp = datetime.datetime.now().strftime("%H%M%S")
        out_path = os.path.join(picks_root(), f"{day}-{stamp}-picks.json")
        n = 2
        while os.path.exists(out_path):
            out_path = os.path.join(picks_root(), f"{day}-{stamp}-{n}-picks.json")
            n += 1
    else:
        os.makedirs(os.path.dirname(os.path.abspath(out_path)), exist_ok=True)
    obj = {"query": "、".join(sorted({p.get("direction") or "" for p in papers})),
           "days": 0,
           "generated": datetime.date.today().isoformat(),
           "source": "lit_digest --pick",
           "count": len(papers),
           "papers": papers}
    tmp = out_path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    os.replace(tmp, out_path)
    if not quiet:
        print(f"已勾选 {len(papers)} 篇 → {out_path}")
        # ⚠️ 这条"下一步"以前是**跑不通的**：lit_fetch 的 --outdir 是必填项，
        #    照抄旧输出会直接报错。命令必须自洽。
        print(f'  下一步：python tools/lit_fetch.py --in "{out_path}" '
              f'--outdir raw/pdf --label "<方向>"')
    return out_path, len(papers)


def mark_digest(day_dir, picked_ids, quiet=False):
    """在 digest.md 里把已勾选项的 `[  ]` 改成 `[x]`（纯视图，不影响 JSON）。"""
    p = os.path.join(day_dir, "digest.md")
    if not os.path.exists(p):
        return False
    text = K.read_text(p)
    status, results, day, _ = load_day(day_dir)
    slugs = all_slugs(status, results)
    lines = text.split("\n")
    out, cur_slug, idx = [], None, 0
    changed = 0
    for ln in lines:
        m = re.match(r"^##\s+.*（([A-Za-z0-9._\-]+)）", ln)
        if m:
            cur_slug, idx = m.group(1), 0
            out.append(ln)
            continue
        m2 = re.match(r"^(\d+)\.\s+\[(\s*|x|OA)\]", ln)
        if m2 and cur_slug:
            idx += 1
            if f"{cur_slug}#{idx}" in picked_ids:
                new = re.sub(r"^(\d+)\.\s+\[(\s*|OA)\]", r"\1. [x]", ln, count=1)
                if new != ln:
                    changed += 1
                out.append(new)
                continue
        out.append(ln)
    if changed:
        _write_text(p, "\n".join(out))
        if not quiet:
            print(f"已在摘要中标记 {changed} 项为 [x]：{p}")
    return bool(changed)


# ---------------------------------------------------------------- 旧摘要解析（兼容）

def parse_digest(path):
    """把既有 digest.md 解析回条目（**字段有损**：无 oa_url / authors_all / tier 细节）。"""
    text = K.read_text(path)
    items, cur = [], None
    for ln in text.split("\n"):
        m = re.match(r"^##\s+(.+?)（([A-Za-z0-9._\-]+)）", ln)
        if m:
            cur = {"label": m.group(1), "slug": m.group(2)}
            continue
        m2 = re.match(r"^(\d+)\.\s+\[(\s*|x|OA)\]\s+\*\*(.+?)\*\*\s*$", ln)
        if m2 and cur:
            items.append({"dir": cur["label"], "slug": cur["slug"],
                          "idx": int(m2.group(1)), "oa": m2.group(2).strip() == "OA",
                          "title": m2.group(3)})
            continue
        if items:
            m3 = re.match(r"^\s+-\s+(.+?)\s+·\s+(\d{4}-\d{2}-\d{2})", ln)
            if m3 and "journal" not in items[-1]:
                items[-1]["journal"] = m3.group(1).strip()
                items[-1]["date"] = m3.group(2)
                mr = re.search(r"相关度\s+([\d.]+)", ln)
                if mr:
                    items[-1]["rel"] = float(mr.group(1))
                mc = re.search(r"通讯\s+(.+)$", ln)
                if mc:
                    items[-1]["corr"] = mc.group(1).strip()
                continue
            m4 = re.match(r"^\s+-\s+DOI:\s+(\S+)", ln)
            if m4 and "doi" not in items[-1]:
                u = m4.group(1)
                items[-1]["doiurl"] = u
                items[-1]["doi"] = re.sub(r"^https?://doi\.org/", "", u)
                if items[-1]["doi"] == "—":
                    items[-1]["doi"] = ""
                continue
    return items


def parse_to_candidates(path):
    """旧摘要 → 尽力还原成候选 JSON（会标注 lossy，并把缺失字段留空而不是编造）。"""
    items = parse_digest(path)
    papers = []
    for it in items:
        papers.append({
            "title": it.get("title", ""), "journal": it.get("journal", ""),
            "publication_date": it.get("date", ""), "doi": it.get("doi", ""),
            "relevance": it.get("rel", 0), "is_oa": bool(it.get("oa")),
            "oa_url": "", "corresponding_author": it.get("corr", ""),
            "main_authors": "", "authors_all": [], "journal_tier": "",
            "ingest_depth": "", "direction": it.get("slug", ""),
            "_lossy": "由 digest.md 解析，oa_url/authors/tier 缺失，建议改用 --pick 从候选 JSON 取",
        })
    return papers, items


# ---------------------------------------------------------------- 自检

def selftest():
    print("=== lit_digest --selftest ===")
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    status = {"day": "2026-10-09", "window": "近一周",
              "directions": [{"slug": "battery", "label": "电池", "limit": 15, "ok": True},
                             {"slug": "oer", "label": "OER 电催化", "ok": False,
                              "error": "rc=3221225786"}]}
    results = {"battery": [
        {"title": "B1", "journal": "JACS", "publication_date": "2026-10-02",
         "doi": "10.1/a", "relevance": 1.0, "is_oa": True, "journal_tier": "T0",
         "corresponding_author": "A", "oa_url": "https://example.org/b1.pdf",
         "authors_all": ["A B", "C D"], "main_authors": "A B"},
        {"title": "B2", "journal": "Nat. Energy", "publication_date": "2026-10-03",
         "doi": "10.1/b", "relevance": 0.8, "is_oa": False, "journal_tier": "T1",
         "oa_url": "", "authors_all": []},
    ], "oer": []}
    md = build_digest("2026-10-09", status, results, window="近一周")
    chk("摘要保留既有格式（## 方向（slug）— N 篇）", "## 电池（battery）— 2 篇" in md)
    chk("摘要显示失败方向", "❌ 本次运行失败" in md and "rc=3221225786" in md)
    chk("摘要含合计", "**合计 2 篇候选**（2 个方向）" in md)
    chk("摘要含 tier（新增信息）", "T0" in md and "T1" in md)
    chk("摘要给出勾选命令提示", "--pick" in md)

    # ID 展开：单点 / 区间 / all
    ids = iter_ids("battery#2", results)
    chk("单点 ID", len(ids) == 1 and ids[0][2]["title"] == "B2")
    ids = iter_ids("battery#1-2,all", results)
    chk("区间 + all 展开", len(ids) == 4, str(len(ids)))
    try:
        iter_ids("nope#1", results)
        chk("未知方向报错", False)
    except SystemExit:
        chk("未知方向报错", True)

    # 过滤器
    f = apply_filters(iter_ids("all", results), min_rel=0.9)
    chk("--min-rel 过滤生效", len(f) == 1 and f[0][2]["title"] == "B1")
    f = apply_filters(iter_ids("all", results), only_oa=True)
    chk("--only-oa 过滤生效", len(f) == 1 and f[0][2]["doi"] == "10.1/a")

    # 落盘：picks JSON 必须保留全字段
    tmp = K.selftest_tmp("digest") if hasattr(K, "selftest_tmp") else None
    import shutil
    import tempfile
    tmp = tmp or os.path.join(tempfile.gettempdir(), "lit_digest_selftest")
    os.makedirs(tmp, exist_ok=True)
    try:
        p, n = write_picks(iter_ids("battery#1", results), "2026-10-09",
                           out_path=os.path.join(tmp, "picks.json"), quiet=True)
        obj = json.load(open(p, encoding="utf-8"))
        paper = obj["papers"][0]
        chk("picks JSON 是 lit_fetch 可吃的形状",
            set(["query", "days", "papers"]) <= set(obj.keys()) and n == 1)
        chk("picks 保留 oa_url/tier/authors 字段（零损失）",
            "oa_url" in paper and paper.get("journal_tier") == "T0"
            and "authors_all" in paper)
        chk("picks 带 pick_id 便于追溯", paper.get("pick_id") == "battery#1")

        # 🆕 2026-10-10：运行产物不得落 _archive/（本轮迁移的核心纪律）
        g = globals()
        orig_ov = g["_RUNS_OVERRIDE"]
        try:
            g["_RUNS_OVERRIDE"] = tmp
            chk("runs_root 不落 _archive/",
                "_archive" not in runs_root().replace("\\", "/"))
            chk("runs_root 可派生 daily/picks 子目录",
                daily_root().endswith("daily") and picks_root().endswith("picks"))
            # 同日两次勾选必须产出两个不同文件（旧版会静默覆盖第一次）
            a, _ = write_picks(iter_ids("battery#1", results), "2026-10-09", quiet=True)
            b, _ = write_picks(iter_ids("battery#2", results), "2026-10-09", quiet=True)
            chk("同日两次 --pick 不互相覆盖", a != b and os.path.exists(a) and os.path.exists(b))
        finally:
            g["_RUNS_OVERRIDE"] = orig_ov

        # 旧摘要往返
        d = os.path.join(tmp, "digest.md")
        with open(d, "w", encoding="utf-8", newline="\n") as f:
            f.write(md)
        papers, items = parse_to_candidates(d)
        chk("旧摘要可解析回条目", len(items) == 2 and items[0]["doi"] == "10.1/a")
        chk("旧摘要解析标注 lossy 并留空而非编造",
            papers[0].get("_lossy") and papers[0]["oa_url"] == ""
            and papers[0]["authors_all"] == [])
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


# ---------------------------------------------------------------- CLI

def main():
    ap = argparse.ArgumentParser(
        description="每日摘要：渲染、审阅与勾选（勾选直接在候选 JSON 上做，零字段损失）")
    ap.add_argument("--day", default="", help="日期 YYYY-MM-DD（默认最近一天）")
    ap.add_argument("--window", default="", help="摘要头部显示的时间窗文案")
    ap.add_argument("--render", action="store_true", help="从候选 JSON 重新生成摘要")
    ap.add_argument("--with-ids", action="store_true", help="摘要里显示可勾选 ID")
    ap.add_argument("--no-results-copy", action="store_true", help="不写库外副本")
    ap.add_argument("--list", action="store_true", help="列出可勾选的 ID")
    ap.add_argument("--pick", default="", help="勾选，如 \"battery#1,oer#2-5\" 或 all")
    ap.add_argument("--out", default="",
                    help="picks JSON 落点（默认 <runs_dir>/picks/<日期>-<时分秒>-picks.json）")
    ap.add_argument("--min-rel", type=float, default=None, help="勾选时过滤相关度下限")
    ap.add_argument("--only-oa", action="store_true", help="只勾选 OA 文献")
    ap.add_argument("--limit", type=int, default=0, help="勾选数量上限")
    ap.add_argument("--mark", action="store_true", help="在摘要里把已勾选项标为 [x]")
    ap.add_argument("--parse", default="", help="解析旧 digest.md → 候选 JSON（字段有损）")
    ap.add_argument("--stats", action="store_true", help="各日候选统计")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    if args.parse:
        papers, items = parse_to_candidates(args.parse)
        # 兼容旧摘要的解析产物**留在 runs 根的 runs/ 子目录**（不再往归档层写，
        # 也不放在 daily/ 里污染"每日运行目录"的语义）。
        out = args.out or os.path.join(runs_root(), "runs", "digest-parsed.json")
        os.makedirs(os.path.dirname(os.path.abspath(out)), exist_ok=True)
        tmp = out + ".tmp"
        with open(tmp, "w", encoding="utf-8", newline="\n") as f:
            json.dump({"query": "（由旧摘要解析）", "days": 0,
                       "generated": datetime.date.today().isoformat(),
                       "papers": papers}, f, ensure_ascii=False, indent=2)
        os.replace(tmp, out)
        print(f"解析出 {len(items)} 条 → {out}")
        print("⚠️ 该路径字段有损（无 oa_url / authors_all / tier）；"
              "新流程请用 --pick 直接勾选候选 JSON。")
        return 0

    if args.stats:
        for dd in day_dirs(args.day or None):
            status, results, day, win = load_day(dd)
            total = sum(len(v) for v in results.values())
            errs = [d.get("slug") for d in (status.get("directions") or [])
                    if isinstance(d, dict) and d.get("error")]
            print(f"{day}  方向 {len(results)}  候选 {total}"
                  + (f"  失败 {errs}" if errs else "")
                  + f"  {os.path.relpath(dd, K.VAULT)}")
        return 0

    if args.render or (not args.pick and not args.list):
        render(day=args.day, window=args.window,
               write_results=not args.no_results_copy, with_ids=args.with_ids)
        if not (args.pick or args.list):
            return 0

    dirs = day_dirs(args.day or None)
    if not dirs:
        raise SystemExit("[!] 没有可用的每日运行目录")
    day_dir = dirs[-1]
    status, results, day, win = load_day(day_dir)

    if args.list:
        for slug in all_slugs(status, results):
            papers = results.get(slug) or []
            print(f"--- {label_of(status, slug)}（{slug}）{len(papers)} 篇")
            for i, p in enumerate(papers, 1):
                flag = "OA" if p.get("is_oa") else "  "
                print(f"  [{flag}] {slug}#{i:<3} rel={p.get('relevance'):<4} "
                      f"{p.get('journal_tier',''):<3} {(p.get('title') or '')[:80]}")
        return 0

    if args.pick:
        picked = apply_filters(iter_ids(args.pick, results), min_rel=args.min_rel,
                               only_oa=args.only_oa, limit=args.limit)
        if not picked:
            print("[!] 过滤后没有剩下任何候选（试试放宽 --min-rel 或去掉 --only-oa）")
            return 2
        out, n = write_picks(picked, day, out_path=args.out)
        if args.mark:
            mark_digest(day_dir, {f"{s}#{i}" for s, i, _ in picked})
        print(f"  涉及方向：{', '.join(sorted({s for s, _, _ in picked}))}")
        return 0
    return 0


if __name__ == "__main__":
    sys.exit(main())
